        (long)(
            (char *)counter_b -
            (char *)counter_a
        )
    );

    printf(
        "  A = %ld\n",
        result_a
    );

    if (counter_a != counter_b) {
        printf(
            "  B = %ld\n",
            result_b
        );
    }

    printf(
        "  elapsed = %.3f seconds\n",
